  FT["PH-H1491"] = {"id":"PH-H1491","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1657_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"在达沃省Mabini市镇设立若干村的法案","en":"An Act to Create Certain Barrios in the Municipality of Mabini, Province of Davao","orig":"An Act to Create Certain Barrios in the Municipality of Mabini, Province of Davao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1657","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1657_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1491-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios are constituted into distinct and separate barrios of the Municipality of Mabini, Province of Davao.\nThe sitios of Panibasan Proper and Andili into a barrio to be known as the barrio of Panibasan; the sitios of Cadunan Proper, Anislagan, Malabatuan and Lapinigan into a barrio to be known as the barrio of Cadunan; and the sitios of Tangnanan Proper, Mampising and Tagbalabao into a barrio to be known as the barrio of Tangnanan."}},{"id":"PH-H1491-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1957."}}],"pack":"ph-p21","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Create Certain Barrios in the Municipality of Mabini, Province of Davao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
