  FT["PH-H1516"] = {"id":"PH-H1516","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1682_1957.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在伊洛伊洛省与伊莎贝拉省各设立一处繁育站并为此拨付所需经费的法案","en":"An Act to Establish a Breeding Station in the Province of Iloilo and Another One in the Province of Isabela and to Appropriate the Necessary Funds Therefor","orig":"An Act to Establish a Breeding Station in the Province of Iloilo and Another One in the Province of Isabela and to Appropriate the Necessary Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1682","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-20","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1682_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1516-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the direct supervision of the Director of Animal Industry a breeding station in the Province of Iloilo to be known as the Iloilo Breeding Station and another one in the Province of Isabela to be known as the Isabela Breeding Station."}},{"id":"PH-H1516-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Subject to the promulgation of such rules and regulations not inconsistent with law by the Secretary of Agriculture and Natural Resources, the Director of Animal Industry will establish said breeding stations on suitable public or private land of not less than twenty-five hectares that may be reserved or acquired for the purpose."}},{"id":"PH-H1516-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred thousand pesos is hereby appropriated, out of the funds in the National Treasury not otherwise appropriated; said sum to be spent by the Director of Animal Industry, subject to the approval of the Secretary of Agriculture and Natural Resources, for the purchase of breeding animals; for the purchase of supplies and materials; for the construction of buildings, sheds, corrals and other structures; for the establishment of water system; for salaries and wages; and for other expenses as may be necessary to carry out the purposes of this Act for the fiscal year ending June thirty, nineteen hundred and fifty-eight, and for its operation and maintenance in subsequent years."}},{"id":"PH-H1516-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1957."}}],"pack":"ph-p21","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Establish a Breeding Station in the Province of Iloilo and Another One in the Province of Isabela and to Appropriate the Necessary Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1517"] = {"id":"PH-H1517","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1683_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立San Nicolas市","en":"An Act Creating the Barrio of Tagodtod in the Municipality of San Nicolas, Province of Batangas","orig":"An Act Creating the Barrio of Tagodtod in the Municipality of San Nicolas, Province of Batangas","vi":"Đạo luật thành lập một Barrio Tagodtod tại Đô thị San Nicolas, Tỉnh Batangas","th":"พระราชบัญญัติจัดตั้งบาริโอ Tagodtod ในเทศบาล San Nicolas จังหวัด Batangas","id":"Undang-Undang membentuk sebuah Barrio Tagodtod di Kotamadya San Nicolas, Provinsi Batangas","ms":"Akta menubuhkan sebuah Barrio Tagodtod di Perbandaran San Nicolas, Wilayah Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1683","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1683_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1517-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Tagodtod is separated from the barrio of Munlawin, Municipality of San Nicolas, Province of Batangas, and constituted into a barrio in the said municipality to be known as the barrio of Tagodtod."}},{"id":"PH-H1517-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1957."}}],"pack":"ph-p21"};
