  FT["PH-H1533"] = {"id":"PH-H1533","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1699_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"确定甲米地市 Salaries of Members of 市镇 Board，为此修订第547号联邦法第11条最后款的法案","en":"An Act Fixing the Salaries of the Members of the Municipal Board of the City of Cavite, Amending for the Purpose the Last Paragraph of Section Eleven of Commonwealth Act Numbered Five Hundred Forty-Seven","orig":"An Act Fixing the Salaries of the Members of the Municipal Board of the City of Cavite, Amending for the Purpose the Last Paragraph of Section Eleven of Commonwealth Act Numbered Five Hundred Forty-Seven"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1699","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1699_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1533-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The last paragraph of section eleven of Commonwealth Act Numbered Five hundred forty-seven, otherwise known as the Charter of the City of Cavite, is amended to read as follows:\n\"The Members of the Municipal Board who are not officers or employees of the Government receiving a fixed compensation or salary from public funds, shall each receive an annual compensation of two thousand four hundred pesos.\""}},{"id":"PH-H1533-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1957."}}],"pack":"ph-p21","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Fixing the Salaries of the Members of the Municipal Board of the City of Cavite, Amending for the Purpose the Last Paragraph of Section Eleven of Commonwealth Act Numbered Five Hundred Forty-Seven","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1534"] = {"id":"PH-H1534","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1700_1957.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"取缔菲律宾共产党及类似团体、对加入者予以处罚并为其他目的法案","en":"An Act to Outlaw the Communist Party of the Philippines and Similar Associations, Penalizing Membership Therein, and for Other Purposes","orig":"An Act to Outlaw the Communist Party of the Philippines and Similar Associations, Penalizing Membership Therein, and for Other Purposes"},"level":"law","status":"active","topics":["criminal"],"docNumber":"Republic Act No. 1700","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-20","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1700_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1534-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act shall be known as Anti-Subversion Act."}},{"id":"PH-H1534-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Congress hereby declares the Communist Party of the Philippines to be an organized conspiracy to overthrow the Government of the Republic of the Philippines for the purpose of establishing in the Philippines a totalitarian regime and place the Government under the control and domination of an alien power. The said party and any other organization having the same purpose and their successors are hereby declared illegal and outlawed."}},{"id":"PH-H1534-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"As used in this Act, the term \"Communist Party of the Philippines\" shall mean and include the organizations now known as the Communist Party of the Philippines and its military arm, the Hukbong Mapagpalaya ng Bayan, formerly known as HUKBALAHAPS, and any successors of such organizations."}},{"id":"PH-H1534-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"After the approval of this Act, whoever knowingly, willfully and by overt acts affiliates himself with, becomes or remains a member of the Communist Party of the Philippines and/or its successor or of any subversive association as defined in section two hereof shall be punished by the penalty of arresto mayor and shall be disqualified permanently from holding any public office, appointive and elective, and from exercising the right to vote; in case of a second conviction, the principal penalty shall be prision correctional, and in all subsequent convictions the penalty of prision mayor shall be imposed; and any alien convicted under this Act shall be deported immediately after he shall have served the sentence imposed upon him: Provided , That if such member is an officer or a ranking leader of the Communist Party of the Philippines or of any subversive association as defined in section two hereof, or if such member takes up arms against the Government, he shall be punished by prision mayor to death with all the accessory penalties provided therefor in the Revised Penal Code: And provided, finally , That one who conspires with any other person to overthrow the Government of the Republic of the Philippines or the government of any of its political subdivisions by force, violence, deceit, subversion or other illegal means, for the purpose of placing such Government or political subdivision under the control and domination of any alien power, shall be punished by prision correctional to prision mayor with all the accessory penalties provided therefor in the same Code."}},{"id":"PH-H1534-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"No prosecution under this Act shall be made unless the city or provincial fiscal, or any special attorney or prosecutor duly designated by the Secretary of Justice, as the case may be, finds after due investigation of the facts, that a prima facie case for violation of this Act exists against the accused, and thereafter presents an information in court against the said accused in due form, and certifies under oath that he has conducted a proper preliminary investigation thereof, with notice, whenever it is possible to give the same, to the party concerned, who shall have the right to be represented by counsel, to testify, to have compulsory process for obtaining witnesses in his favor, and to cross-examine witnesses against him: Provided , That the preliminary investigation of any offense defined and penalized herein by prision mayor to death shall be conducted by the proper Court of First Instance."}},{"id":"PH-H1534-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Any person who knowingly furnishes false evidence in any action brought under this Act shall be punished by prision correctional."}},{"id":"PH-H1534-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"No person shall be convicted of any of the offenses penalized herein with prision mayor to death unless on the testimony of at least two witnesses to the same overt act or on confession of the accused in open court."}},{"id":"PH-H1534-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Within thirty days after the approval of this Act, any person who is a member of the Communist Party of the Philippines or of any such association or conspiracy, who desires to renounce such membership, may do so in writing and under oath before a municipal or city mayor, a provincial governor, or a person authorized by law to administer oaths. Such renunciation shall exempt such person or persons from the penal sanction of this Act, but the same shall in no way exempt him from liability for criminal acts or for any violation of the existing laws of the Republic of the Philippines committed before this Act takes effect."}},{"id":"PH-H1534-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Nothing in this Act shall be interpreted as a restriction to freedom of thought, of assembly and of association for purposes not contrary to law as guaranteed by the Constitution."}},{"id":"PH-H1534-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1957"}}],"pack":"ph-p21","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Outlaw the Communist Party of the Philippines and Similar Associations, Penalizing Membership Therein, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1535"] = {"id":"PH-H1535","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1701_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将达沃省Mati市镇Cabuaya村的名称正式变更为Dawan村的法案","en":"An Act Changing the Name of the Barrio of Cabuaya, Municipality of Mati, Province of Davao, to Barrio Dawan","orig":"An Act Changing the Name of the Barrio of Cabuaya, Municipality of Mati, Province of Davao, to Barrio Dawan","vi":"Đạo luật đổi tên Barrio Cabuaya, Thị trấn Mati, Tỉnh Davao thành Barrio Dawan","th":"พระราชบัญญัติเปลี่ยนชื่อบารริโอ Cabuaya, เทศบาล Mati, จังหวัด Davao เป็นบารริโอ Dawan","id":"Undang-Undang mengubah nama Barrio Cabuaya, Kotamadya Mati, Provinsi Davao menjadi Barrio Dawan","ms":"Akta menukar nama Barrio Cabuaya, Perbandaran Mati, Wilayah Davao menjadi Barrio Dawan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1701","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1701_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1535-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the barrio of Cabuaya, Municipality of Mati, Province of Davao, is changed to barrio Dawan."}},{"id":"PH-H1535-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1957."}}],"pack":"ph-p21","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Barrio of Cabuaya, Municipality of Mati, Province of Davao, to Barrio Dawan","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1536"] = {"id":"PH-H1536","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1702_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Calape市","en":"An Act Creating the Barrios of Abucayan Norte and Abucayan Sur, Municipality of Calape, Province of Bohol","orig":"An Act Creating the Barrios of Abucayan Norte and Abucayan Sur, Municipality of Calape, Province of Bohol","vi":"Đạo luật thành lập Barrio Abucayan Norte và Abucayan Sur tại Thị trấn Calape, Tỉnh Bohol","th":"พระราชบัญญัติจัดตั้งบาริโอ Abucayan Norte และ Abucayan Sur ในเทศบาล Calape จังหวัด Bohol","id":"Undang-Undang membentuk Barrio Abucayan Norte dan Abucayan Sur di Kotamadya Calape, Provinsi Bohol","ms":"Akta menubuhkan Barrio Abucayan Norte dan Abucayan Sur di Perbandaran Calape, Wilayah Bohol"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1702","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1702_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1536-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following barrios in the Municipality of Calape, Province of Bohol, are created:\n1. Barrio Abucayan Norte, which shall constitute the sitios of Cabulihan and Cabinong; and\n2. Barrio Abucayan Sur, which shall constitute the sitios of Rama and Bino."}},{"id":"PH-H1536-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1957."}}],"pack":"ph-p21"};
  FT["PH-H1537"] = {"id":"PH-H1537","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1703_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Calape市","en":"An Act Creating Certain Barrios in the Municipality of Calape, Province of Bohol","orig":"An Act Creating Certain Barrios in the Municipality of Calape, Province of Bohol","vi":"Đạo luật thành lập các Barrio tại Đô thị Calape, Tỉnh Bohol","th":"พระราชบัญญัติจัดตั้งบาริโอหลายแห่ง ในเทศบาล Calape จังหวัด Bohol","id":"Undang-Undang membentuk beberapa Barrio di Kotamadya Calape, Provinsi Bohol","ms":"Akta menubuhkan beberapa Barrio di Perbandaran Calape, Wilayah Bohol"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1703","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1703_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1537-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Binogawan, Masonoy, Bintig, Cahayag, and Lawis, Municipality of Calape, Province of Bohol, are converted into barrios of said municipality to be known as the barrios of Binogawan, Masonoy, Bintig, Cahayag, and Lawis, respectively."}},{"id":"PH-H1537-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1957."}}],"pack":"ph-p21"};
